import './performance.css';
const $=s=>document.querySelector(s);
$('#app').innerHTML=`<main><p class="eyebrow">OPENUI / THROWAWAY PERFORMANCE LAB</p><h1>Does streaming stay responsive?</h1><p>Compare equivalent React controls with static CSS against our Goober-generated styling path. Chat and dashboard workloads have equal priority. Type and scroll inside the running example to feel the difference.</p><p class="note"><strong>This is a styling microbenchmark.</strong> The control is not today's react-ui. The chart/table are synthetic, and this does not run the OpenUI parser, Next.js SSR or server pressure tests. A passing run is not full OpenUI approval. Both arms use identical generated CSS to isolate component overhead; payload cost is assessed separately.</p><div class="controls"><label>Workload<select id="scenario"><option value="both">Both: chat + dashboard</option><option value="chat">Chat</option><option value="dashboard">Dashboard</option></select></label><label>Load<select id="count"><option value="25">25 cards / 50 rows or points</option><option value="100" selected>100 cards / 200 rows or points</option><option value="500">500 cards / 1,000 rows or points</option></select></label><label>Incoming chunks / second<select id="rate"><option>20</option><option selected>60</option><option>120</option></select></label><label>Seconds per run<select id="seconds"><option>5</option><option selected>10</option><option>30</option><option>60</option></select></label><label>CSS environment<select id="framework"><option value="plain">Plain CSS</option><option value="tailwind3">Tailwind v3</option><option value="tailwind4">Tailwind v4</option><option value="none">No framework</option></select></label><label>Paired repetitions<select id="pairs"><option selected>1</option><option>3</option><option>5</option></select></label></div><div class="actions"><button id="start" class="primary">Run comparison</button><button id="stop" disabled>Stop</button><button id="export" disabled>Export measurements</button></div><p id="status">Ready. Keep this tab visible. Each arm runs separately in a fresh frame.</p><div id="stage"></div><h2>Run results</h2><p class="muted">Times are milliseconds. Update delay is receipt-to-next-presentation-opportunity, not exact paint time. Larger frame gaps can mean stutter. Browser-specific metrics show “unavailable” when unsupported. Manual interaction makes runs less controlled; repeat unattended for comparison.</p><div class="table-wrap"><table><thead><tr><th>Workload / arm</th><th>Status</th><th>Update p95</th><th>Delivery lag p95</th><th>Frame gap p95</th><th>Input p95</th><th>Long tasks</th><th>CSS rules Δ</th></tr></thead><tbody id="rows"></tbody></table></div><p id="verdict">No measurements yet. There is deliberately no automatic “Goober approved” badge.</p><details><summary>What to try and what these numbers mean</summary><ol><li>Start with both workloads at 100 cards and 60 chunks/second. Type continuously and scroll inside the frame.</li><li>Repeat at 500 cards and 120 chunks/second. Look for delayed typing, accumulated delivery lag, and stalled updates.</li><li>Repeat with Tailwind v3 and v4. Stop and export if something feels wrong.</li><li>Run again without interaction, then reverse the comparison via paired repetitions. More repetitions alternate A/B and B/A.</li></ol><p>The proposed real OpenUI test plan also requires actual components, parser replay, cold-load CSS/JS measurements, SSR concurrency and soak testing. These are pending; this lab is the first diagnostic stage.</p></details><details><summary>Latest raw run</summary><pre id="raw">None</pre></details><p><a href="/">Compatibility dashboard</a> · <a href="/results/DECISION.md">Compatibility report</a> · <a href="https://github.com/ankit-thesys/openui-comp/issues/4">Performance and maintainability decision map</a></p></main>`;
let queue=[],results=[],current=null,frame=null,running=false,cancelled=false,watchdog;
const format=x=>x===null||x===undefined?'unavailable':Number(x).toFixed(1);
function render(){ $('#rows').innerHTML=results.map(r=>`<tr><td>${r.config.scenario} / ${r.config.arm==='generated'?'Generated':'Static control'}</td><td>${r.status}</td><td>${format(r.updateOpportunityP95Ms)}</td><td>${format(r.deliveryLagP95Ms)}</td><td>${format(r.frameGapP95Ms)}</td><td>${format(r.inputOpportunityP95Ms)} (${r.inputSamples})</td><td>${r.longTaskCount??'unavailable'}</td><td>${r.rulesAfter===undefined?'unavailable':r.rulesAfter-r.rulesBefore}</td></tr>`).join('');$('#export').disabled=!results.length;$('#raw').textContent=JSON.stringify(results.at(-1)||{},null,2);const valid=results.filter(r=>r.status==='complete'&&r.finalContentMatches);$('#verdict').textContent=`${valid.length}/${results.length} runs completed with final content matching. Compare repeated paired runs; a single p95 is not a statistically reliable regression verdict.`;window.__performanceResults=results; }
function done(){running=false;clearTimeout(watchdog);$('#start').disabled=false;$('#stop').disabled=true;for(const e of document.querySelectorAll('select'))e.disabled=false;$('#status').textContent=cancelled?'Stopped. Completed and partial measurements remain exportable.':'Finished. Explore the last frame, change the load, or export the measurements.';}
function next(){clearTimeout(watchdog);if(cancelled||!queue.length){done();return;}current=queue.shift();$('#status').textContent=`Running ${current.scenario} / ${current.arm==='generated'?'Goober-generated styles':'static React control'} — ${queue.length} runs remain`;frame=document.createElement('iframe');frame.title=current.scenario+' '+current.arm+' performance fixture';frame.src='/performance-fixture.html?'+new URLSearchParams(current);$('#stage').replaceChildren(frame);watchdog=setTimeout(()=>{results.push({config:current,status:'fixture-timeout'});render();next();},(Number(current.seconds)+20)*1000);}
$('#start').onclick=()=>{results=[];queue=[];cancelled=false;running=true;const scenario=$('#scenario').value;const scenarios=scenario==='both'?['chat','dashboard']:[scenario];const config=Object.fromEntries(['count','rate','seconds','framework'].map(k=>[k,$('#'+k).value]));for(let pair=0;pair<Number($('#pairs').value);pair++)for(const s of scenarios)for(const arm of pair%2?['generated','control']:['control','generated'])queue.push({...config,scenario:s,arm,runId:crypto.randomUUID(),pair});$('#start').disabled=true;$('#stop').disabled=false;for(const e of document.querySelectorAll('select'))e.disabled=true;render();next();};
$('#stop').onclick=()=>{cancelled=true;queue=[];frame?.contentWindow?.postMessage({source:'openui-perf-parent',type:'stop'},location.origin);setTimeout(()=>{if(running)done();},500);};
window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==frame?.contentWindow||e.data?.source!=='openui-perf'||e.data.runId!==current?.runId||!running)return;if(e.data.type==='ready')frame.contentWindow.postMessage({source:'openui-perf-parent',type:'start'},location.origin);if(e.data.type==='progress')$('#status').textContent=`${current.scenario} / ${current.arm}: ${e.data.received}/${e.data.total} chunks — ${queue.length} runs remain`;if(e.data.type==='result'){results.push(e.data.result);render();next();}});
$('#export').onclick=()=>{const data={exportedAt:new Date().toISOString(),scope:'Synthetic UI-only styling comparison; real OpenUI and SSR pressure remain pending',userAgent:navigator.userAgent,hardwareConcurrency:navigator.hardwareConcurrency,results};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='openui-performance-'+Date.now()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
